export default test({
	html: `
		<button>clicks: 0</button>
		<p>pending...</p>
	`,

	compileOptions: {
		// this tests some behaviour that was broken in dev
		dev: true
	},

	async test({ assert, target }) {
		await tick();

		assert.htmlEqual(
			target.innerHTML,
			`
				<button>clicks: 0</button>
				<p>0</p>
			`
		);

		let [button] = target.querySelectorAll('button');
		let [p] = target.querySelectorAll('p');

